🐛 Describe the bug
Repro:
import torch

class ModuleA(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.linear = torch.nn.Linear(4, 4)

    def forward(self, x):
        return self.linear(x)

class ModuleB(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.a = ModuleA()

    def forward(self, x):
        return self.a(x).relu()

mod = ModuleB()
torch.jit.script(mod)

with torch.profiler.profile(with_stack=True, schedule=torch.profiler.schedule(warmup=2, wait=2, active=3, repeat=1)) as prof:
    for _ in range(10):
        x = torch.rand(4, 4)
        mod(x)
        prof.step()

prof.export_chrome_trace("torchscript_stack.json")
Result: segfault.
